mapper.select:
/* InterfaceMapper.selectInterfaceList 조회 조건에 맞는 인터페이스 목록을 인터페이스ID 순으로 조회 (허용 기관 수 포함) */ SELECT I.INFC_ID, I.INFC_NM, I.HTTP_METH_NM, I.URL, I.BODY_LOG_YN, I.MASK_FLD_CONT, I.USE_YN, I.RMK, (SELECT COUNT(*) FROM TB_LNK_ORG_INFC_R R WHERE R.INFC_ID = I.INFC_ID AND R.USE_YN = 'Y') AS ALLW_ORG_CNT FROM TB_INFC_M I
AND (UPPER(I.INFC_ID) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(I.INFC_NM) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(I.URL) LIKE '%' || UPPER(TRIM(#{keyword})) || '%')
AND I.USE_YN = #{useYn}
ORDER BY I.INFC_ID

/* InterfaceMapper.selectInterfaceCount 인터페이스ID 목록 중 등록된 인터페이스 수를 조회 */
SELECT COUNT(*)
FROM TB_INFC_M
WHERE INFC_ID IN

    #{infcId}

mapper.insert:
/* InterfaceMapper.insertInterface 인터페이스를 등록 */
INSERT INTO TB_INFC_M (
    INFC_ID, INFC_NM, HTTP_METH_NM, URL, BODY_LOG_YN, MASK_FLD_CONT, USE_YN, RMK,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.infcId}, #{item.infcNm}, #{item.httpMethNm}, #{item.url}, #{item.bodyLogYn},
    NULLIF(#{item.maskFldCont}, ''), #{item.useYn}, NULLIF(#{item.rmk}, ''),
    #{usrId}, CURRENT_TIMESTAMP, #{usrId}, CURRENT_TIMESTAMP
)
